using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Microsoft.Win32;

namespace DeskBloom {
  internal static class SettingsCleanupTests {
    private static void Assert(bool value,string message){if(!value)throw new Exception(message);}
    private static void CheckShellCleanup(){string scope="Software\\DeskBloomCleanupTests\\"+Guid.NewGuid().ToString("N"),classes=scope+"\\Classes",run=scope+"\\Run";try{using(var key=Registry.CurrentUser.CreateSubKey(classes+"\\*\\shell\\DeskBloom.Add\\command"))key.SetValue("","Fixture");using(var key=Registry.CurrentUser.CreateSubKey(classes+"\\DeskBloom.Group\\shell\\open\\command"))key.SetValue("","Fixture");using(var key=Registry.CurrentUser.CreateSubKey(classes+"\\.groups"))key.SetValue("","OtherApp");using(var key=Registry.CurrentUser.CreateSubKey(run)){key.SetValue("DeskBloom","Fixture");key.SetValue("OtherApp","Keep");}ShellIntegration.Remove(classes,run);using(var key=Registry.CurrentUser.OpenSubKey(classes+"\\*\\shell\\DeskBloom.Add"))Assert(key==null,"owned Explorer command removed");using(var key=Registry.CurrentUser.OpenSubKey(classes+"\\.groups",true)){Assert((string)key.GetValue("")=="OtherApp","foreign extension association preserved");key.SetValue("","DeskBloom.Group");}using(var key=Registry.CurrentUser.OpenSubKey(run))Assert(key.GetValue("DeskBloom")==null&&(string)key.GetValue("OtherApp")=="Keep","only DeskBloom startup value removed");ShellIntegration.Remove(classes,run);using(var key=Registry.CurrentUser.OpenSubKey(classes+"\\.groups"))Assert(key==null,"empty owned association key removed");}finally{Registry.CurrentUser.DeleteSubKeyTree(scope,false);}}
    internal static void Run(string directory,List<string> log){string previousLanguage=L.Language;string test=Path.Combine(directory,"settings-cleanup"),root=Path.Combine(test,"Data"),groups=Path.Combine(test,"Groups"),desktop=Path.Combine(test,"Desktop");var store=new Store(root,groups,desktop);var group=store.CreateGroup("Restorable");group.X=214;group.Y=86;group.Open=false;group.Color=8;group.BackgroundColor=4;group.TitleParts=new List<TitlePart>{new TitlePart {Text=group.Name,Bold=true,Color=3}};store.State.Language=L.SystemLanguage=="ru"?"en":"ru";string file=Path.Combine(group.FolderPath,"must-survive.txt");File.WriteAllText(file,"User content");string image=Path.Combine(test,"custom.png");var pixels=new byte[16*16*4];for(int n=3;n<pixels.Length;n+=4)pixels[n]=255;var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(BitmapSource.Create(16,16,96,96,PixelFormats.Bgra32,null,pixels,64)));using(var stream=File.Create(image))encoder.Save(stream);GroupAssets.SetIcon(store,group,image);store.Save();string document=PortableLayouts.DocumentPath(group),icon=GroupAssets.IconPath(store,group);byte[] descriptor=File.ReadAllBytes(document),asset=File.ReadAllBytes(icon);string appearance=Appearance.Key(group);
      foreach(string folder in new[]{"Files","DesktopPages","Wallpapers","Screenshots"})Directory.CreateDirectory(Path.Combine(root,folder));Directory.CreateDirectory(Path.Combine(root,"Requests"));foreach(string suffix in new[]{".json",".json.tmp",".json.invalid"})File.WriteAllText(Path.Combine(root,"Requests",Guid.NewGuid().ToString("N")+suffix),"stale request");File.WriteAllText(Path.Combine(root,"group-folder-move.json.tmp"),"stale journal");Assert(SettingsCleanup.Remove(root),"settings cleanup succeeds");Assert(!Directory.Exists(root),"empty global settings directory is removed completely");Assert(File.ReadAllText(file)=="User content"&&File.ReadAllBytes(document).SequenceEqual(descriptor)&&File.ReadAllBytes(icon).SequenceEqual(asset),"group files, .groups document and custom icon stay byte-identical");
      var reloaded=new Store(root,groups,desktop);var restored=reloaded.State.Groups.Single(g=>g.Id==group.Id);Assert(restored.Name==group.Name&&restored.X==214&&restored.Y==86&&!restored.Open&&Appearance.Key(restored)==appearance,"group identity, layout, formatting, colors and icon restore from .groups");Assert(reloaded.State.Language==L.SystemLanguage,"application language preference resets");reloaded.Save();Assert(SettingsCleanup.Remove(root)&&!Directory.Exists(root),"second cleanup is safe");Assert(SettingsCleanup.Remove(root)&&!Directory.Exists(root),"absent settings are never recreated");
      string nested=Path.Combine(test,"NestedData");var nestedStore=new Store(nested);var nestedGroup=nestedStore.CreateGroup("Nested user group");string nestedFile=Path.Combine(nestedGroup.FolderPath,"keep.txt");File.WriteAllText(nestedFile,"Keep");Assert(SettingsCleanup.Remove(nested)&&File.ReadAllText(nestedFile)=="Keep"&&File.Exists(PortableLayouts.DocumentPath(nestedGroup)),"legacy groups inside the settings root are preserved");Assert(!File.Exists(Path.Combine(nested,"state.json"))&&!Directory.Exists(Path.Combine(nested,"Requests")),"nested group preservation never preserves global configuration");
      string mixed=Path.Combine(test,"MixedData");var mixedStore=new Store(mixed,Path.Combine(test,"MixedGroups"));mixedStore.Save();Directory.CreateDirectory(Path.Combine(mixed,"Requests"));string unknown=Path.Combine(mixed,"Requests","personal.txt");File.WriteAllText(unknown,"Not a cache");Assert(SettingsCleanup.Remove(mixed)&&File.ReadAllText(unknown)=="Not a cache"&&!File.Exists(Path.Combine(mixed,"state.json")),"unknown user files in a cache directory are never erased");
      string foreign=Path.Combine(test,"Foreign");Directory.CreateDirectory(foreign);File.WriteAllText(Path.Combine(foreign,"state.json"),"{\"Version\":99}");Assert(!SettingsCleanup.Remove(foreign)&&File.Exists(Path.Combine(foreign,"state.json")),"an unrelated directory is not accepted as an application settings root");
      CheckShellCleanup();L.Language=previousLanguage;log.Add("PASS: uninstall cleanup removes global state, backups, layout cache and owned requests without recreating them; .groups, files and custom icons stay intact; groups restore after reinstall; unknown and legacy user files are preserved.");}
  }
}
